import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

public class Main {

    static char[] data;
    static int result = 0;
    static int xValue = 0;

    // iterative equivalent using explicit stack (List of states)
    static void countDivisible(int[] starts) {
        // starts is a single-element array to allow recursion simulation? Not done.
        // We will keep recursion but rename.
    }

    static void recurse(int idx, int accum) {
        if (idx >= data.length) {
            if (accum % 25 == 0) result++;
            return;
        }
        int dig = data[idx] - '0';
        if (dig >= 0 && dig <= 9) {
            recurse(idx + 1, accum * 10 + dig);
        } else if (data[idx] == 'X') {
            recurse(idx + 1, accum * 10 + xValue);
        } else { // '_'
            if (idx == data.length - 1) {
                recurse(idx + 1, accum * 10 + 5);
                recurse(idx + 1, accum * 10);
            } else {
                int start = (idx == 0) ? 1 : 0;
                for (int i = start; i < 10; i++) {
                    recurse(idx + 1, accum * 10 + i);
                }
            }
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        String input = reader.readLine();
        reader.close();
        if (input == null) {
            System.out.println(0);
            return;
        }
        // take first token
        String firstToken = input.split("\\s+")[0];
        data = firstToken.toCharArray();
        int n = data.length;
        if (data[0] == '0' && n != 1) {
            System.out.println(0);
            return;
        }
        boolean hasX = false;
        for (char c : data) {
            if (c == 'X') {
                hasX = true;
                break;
            }
        }
        if (hasX) {
            for (int v = 0; v < 10; v++) {
                if (data[0] == 'X' && n > 1 && v == 0) continue;
                xValue = v;
                recurse(0, 0);
            }
        } else {
            recurse(0, 0);
        }
        System.out.println(result);
    }
}
